 @SubscribeEvent(priority=EventPriority.LOWEST) public static void shield(ShieldBlockEvent e){if(!e.getEntity().level().isClientSide)event("native-shield-block",e.getEntity(),Map.of("useTicks",e.getEntity().getTicksUsingItem(),"blocked",e.getBlockedDamage(),"original",e.getOriginalBlockedDamage(),"data",e.getEntity().getPersistentData().toString()));}
 @SubscribeEvent(priority=EventPriority.HIGHEST) public static void fallBefore(TickEvent.PlayerTickEvent e){if(e.phase==TickEvent.Phase.END&&e.player instanceof ServerPlayer p){FALL_START.put(p,p.getDeltaMovement().y);FOOD_START.put(p,(double)p.getFoodData().getExhaustionLevel());var d=p.getPersistentData();MOVE_START.put(p,p.position().distanceToSqr(new Vec3(d.getDouble("cod4X"),d.getDouble("cod4Y"),d.getDouble("cod4Z"))));}}
 @SubscribeEvent(priority=EventPriority.LOWEST) public static void foodAfter(TickEvent.PlayerTickEvent e){if(e.phase==TickEvent.Phase.END&&e.player instanceof ServerPlayer p&&active>=0&&set(active).equals("cloth")&&count(active)==4&&EquipmentBehaviors.pieces(p,"cloth")>=4&&p.isSprinting()&&MOVE_START.getOrDefault(p,0D)>0&&MOVE_START.get(p)<4)event("cloth-native-refund",p,Map.of("refund",FOOD_START.get(p)-p.getFoodData().getExhaustionLevel(),"expected",Math.sqrt(MOVE_START.get(p))*.1));}
 @SubscribeEvent(priority=EventPriority.LOWEST) public static void knockback(LivingKnockBackEvent e){if(!e.getEntity().level().isClientSide)event("knockback-native",e.getEntity(),Map.of("strength",e.getStrength(),"x",e.getRatioX(),"z",e.getRatioZ()));}
 @SubscribeEvent(priority=EventPriority.LOWEST) public static void fallAfter(TickEvent.PlayerTickEvent e){if(e.phase==TickEvent.Phase.END&&e.player instanceof ServerPlayer p&&active>=0&&set(active).equals("sky")&&count(active)==2&&EquipmentBehaviors.pieces(p,"sky")>=2&&FALL_START.getOrDefault(p,0D)<-.15&&!p.onGround())event("sky-native-tick",p,Map.of("beforeY",FALL_START.get(p),"afterY",p.getDeltaMovement().y));}
 @SubscribeEvent public static void equipment(LivingEquipmentChangeEvent e){if(e.getEntity() instanceof ServerPlayer p&&active>=0){event("equipment-native",p,Map.of("slot",e.getSlot().toString(),"from",e.getFrom().toString(),"to",e.getTo().toString()));if(phase==0&&p.getGameProfile().getName().endsWith("Peer")&&e.getSlot().getType()==EquipmentSlot.Type.ARMOR&&!e.getTo().isEmpty())nativeClicks++;}}
 @SubscribeEvent(priority=EventPriority.HIGHEST) public static void raw(LivingHurtEvent e){if(!e.getEntity().level().isClientSide)RAW.put(e,e.getAmount());}
 @SubscribeEvent(priority=EventPriority.LOWEST,receiveCanceled=true) public static void hurt(LivingHurtEvent e){if(!e.getEntity().level().isClientSide)event("hurt-final",e.getEntity(),obj("raw",RAW.getOrDefault(e,e.getAmount()),"amount",e.getAmount(),"canceled",e.isCanceled(),"sourceOwner",e.getSource().getEntity()==null?"none":e.getSource().getEntity().getUUID().toString(),"damageType",e.getSource().type().msgId(),"sourceType",e.getSource().getEntity()==null?"none":ForgeRegistries.ENTITY_TYPES.getKey(e.getSource().getEntity().getType()).toString(),"sourceEntity",e.getSource().getEntity()==null?-1:e.getSource().getEntity().getId(),"sourceData",e.getSource().getEntity()==null?"none":e.getSource().getEntity().getPersistentData().toString()));}
 @SubscribeEvent(priority=EventPriority.LOWEST,receiveCanceled=true) public static void attack(LivingAttackEvent e){if(!e.getEntity().level().isClientSide)event("attack-final",e.getEntity(),Map.of("amount",e.getAmount(),"canceled",e.isCanceled(),"fire",e.getSource().is(net.minecraft.tags.DamageTypeTags.IS_FIRE)));}
 @SubscribeEvent(priority=EventPriority.LOWEST,receiveCanceled=true) public static void fall(LivingFallEvent e){if(!e.getEntity().level().isClientSide)event("fall-event",e.getEntity(),Map.of("distance",e.getDistance(),"canceled",e.isCanceled()));}
 @SubscribeEvent(priority=EventPriority.LOWEST,receiveCanceled=true) public static void impact(net.minecraftforge.event.entity.ProjectileImpactEvent e){if(!e.getProjectile().level().isClientSide&&e.getProjectile() instanceof net.minecraft.world.entity.projectile.AbstractArrow a&&e.getRayTraceResult() instanceof EntityHitResult h&&h.getEntity() instanceof LivingEntity p)event("projectile-impact",p,Map.of("canceled",e.isCanceled(),"projectileOwner",a.getOwner()==null?"none":a.getOwner().getUUID().toString()));}
 @SubscribeEvent public static void added(MobEffectEvent.Added e){if(!e.getEntity().level().isClientSide&&e.getEffectInstance().getEffect()==ExpansionEffects.STAGGER.get())event("stagger-added",e.getEntity(),Map.of("duration",e.getEffectInstance().getDuration()));}
 @SubscribeEvent public static void use(PlayerInteractEvent.RightClickItem e){if(!e.getEntity().level().isClientSide)event("use-native",e.getEntity(),Map.of("item",e.getItemStack().toString()));}
 @SubscribeEvent(priority=EventPriority.LOWEST,receiveCanceled=true) public static void step(net.minecraftforge.event.PlayLevelSoundEvent.AtEntity e){if(e.getEntity() instanceof ServerPlayer sp&&active==53&&e.getSound()!=null)event("native-step-sound",sp,Map.of("sound",e.getSound().value().getLocation().toString(),"canceled",e.isCanceled(),"crouch",sp.isShiftKeyDown()));if(e.getEntity() instanceof net.minecraft.world.entity.player.Player p&&e.getSound()!=null&&e.getSound().value().getLocation().getPath().endsWith(".step")&&e.isCanceled()&&p.level().isClientSide&&p==Minecraft.getInstance().player)try{mark(ROLE+"-footstep-canceled-"+local);}catch(Exception ignored){}}
 @SubscribeEvent public static void sound(net.minecraftforge.event.PlayLevelSoundEvent.AtPosition e){if(!e.getLevel().isClientSide()&&e.getSound()!=null&&e.getSound().value().getLocation().getPath().equals("item.shield.block")&&active>=0)event("shield-sound",players(server).get(1),Map.of("sound",e.getSound().value().getLocation().toString()));}
